$isi = $surat['isi_surat'] ?? ''; $nomor = $surat['nomor_surat'] ?? ''; $tanggal = $surat['tanggal_moc'] ?? date('Y-m-d');
function spm_value($label, $default = '') { global $isi, $surat; if (preg_match('/^' . preg_quote($label, '/') . '\\s*:\\s*(.+)$/im', $isi, $m)) return trim($m[1]); if ($label === 'Mentor' && !empty($surat['tujuan'])) return $surat['tujuan']; return $default; }
function spm_date($date) { $bulan = [1=>'Januari',2=>'Februari',3=>'Maret',4=>'April',5=>'Mei',6=>'Juni',7=>'Juli',8=>'Agustus',9=>'September',10=>'Oktober',11=>'November',12=>'Desember']; $time = strtotime($date) ?: time(); return date('j', $time) . ' ' . $bulan[(int)date('n', $time)] . ' ' . date('Y', $time); }
?>
